"""Minimal, dependency-free client for OpenAI's Responses API.

The client does not log or persist prompts, responses, or API keys.  Set
``OPENAI_API_KEY`` in the environment, or pass ``api_key`` explicitly.
"""

from __future__ import annotations

import json
import os
from typing import Any, Mapping
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = "https://api.openai.com/v1/responses"


class OpenAIResponsesError(RuntimeError):
    """Raised when a request to the Responses API cannot be completed."""


class OpenAIResponsesClient:
    """Small synchronous Responses API client using only Python's stdlib."""

    def __init__(
        self,
        api_key: str | None = None,
        *,
        model: str = "gpt-4.1-mini",
        timeout: float = 60.0,
        endpoint: str = API_URL,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("Set OPENAI_API_KEY or pass api_key explicitly")
        if not model:
            raise ValueError("model must not be empty")
        if timeout <= 0:
            raise ValueError("timeout must be greater than zero")
        self.model = model
        self.timeout = timeout
        self.endpoint = endpoint

    def create_response(self, prompt: str) -> Mapping[str, Any]:
        """Send one private text prompt and return the decoded API response.

        This method keeps the prompt and response in memory only.  It does not
        write them to disk or print them.
        """
        if not isinstance(prompt, str) or not prompt.strip():
            raise ValueError("prompt must be a non-empty string")

        payload = json.dumps({"model": self.model, "input": prompt}).encode("utf-8")
        request = Request(
            self.endpoint,
            data=payload,
            headers={
                "Accept": "application/json",
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
            },
            method="POST",
        )

        try:
            with urlopen(request, timeout=self.timeout) as response:
                body = response.read()
        except HTTPError as exc:
            raise OpenAIResponsesError(
                f"Responses API returned HTTP {exc.code}"
            ) from exc
        except URLError as exc:
            raise OpenAIResponsesError("Could not reach the Responses API") from exc
        except TimeoutError as exc:
            raise OpenAIResponsesError("The Responses API request timed out") from exc

        try:
            decoded = json.loads(body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise OpenAIResponsesError("Responses API returned invalid JSON") from exc
        if not isinstance(decoded, dict):
            raise OpenAIResponsesError("Responses API returned an unexpected JSON value")
        return decoded

    def create_text(self, prompt: str) -> str:
        """Send a prompt and return the generated text."""
        response = self.create_response(prompt)
        text = response.get("output_text")
        if isinstance(text, str):
            return text

        # Fallback for response representations that omit the convenience
        # output_text field.
        chunks: list[str] = []
        output = response.get("output", [])
        if isinstance(output, list):
            for item in output:
                if not isinstance(item, dict):
                    continue
                content = item.get("content", [])
                if not isinstance(content, list):
                    continue
                for part in content:
                    if isinstance(part, dict) and part.get("type") == "output_text":
                        value = part.get("text")
                        if isinstance(value, str):
                            chunks.append(value)
        if chunks:
            return "".join(chunks)
        raise OpenAIResponsesError("Responses API response contained no output text")


def send_prompt(prompt: str, **kwargs: Any) -> str:
    """Convenience wrapper returning generated text for one prompt."""
    return OpenAIResponsesClient(**kwargs).create_text(prompt)


__all__ = [
    "API_URL",
    "OpenAIResponsesClient",
    "OpenAIResponsesError",
    "send_prompt",
]
